// Object pool for particles or frequent allocations
class Pool {
  constructor(factory, reset, size = 50) {
    this.factory = factory;
    this.reset = reset;
    this.items = Array.from({ length: size }, factory);
  }
  acquire() {
    return this.items.length ? this.items.pop() : this.factory();
  }
  release(item) {
    this.reset(item);
    this.items.push(item);
  }
}

const particlePool = new Pool(
  () => ({ x: 0, y: 0, vx: 0, vy: 0 }),
  (p) => { p.x = 0; p.y = 0; p.vx = 0; p.vy = 0; }
);

// Typed arrays for numeric data
function processSamples(samples) {
  const out = new Float32Array(samples.length);
  for (let i = 0; i < samples.length; i++) {
    out[i] = samples[i] * 1.5;
  }
  return out;
}

